function installClock(nowIso) {
  if (globalThis.__sheetSmokeClock) return;
  const Real = Date;
  const offset = Real.parse(nowIso) - Real.now();
  class FixtureDate extends Real {
    constructor(...a) { super(...(a.length ? a : [Real.now() + offset])); }
    static now() { return Real.now() + offset; }
  }
  globalThis.Date = FixtureDate;
  globalThis.__sheetSmokeClock = true;
}

// Daily bars: 70 sessions ending Wed Oct 14 (weekdays only), a climb in waves, AAPL's last three days the fixture's.
function dailyBars(symbol, live) {
  const out = [];
  const end = Date.parse('2026-10-14T12:00:00.000Z');
  let s = symbol.length * 7 + 3;
  const rnd = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  const days = [];
  for (let k = 0; days.length < 70; k += 1) {
    const d = new Date(end - k * 86400000);
    if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) days.push(d.toISOString().slice(0, 10));
  }
  days.reverse().forEach((date, i) => {
    const base = live * (0.86 + 0.14 * (i / 69)) + live * 0.02 * Math.sin(i / 4) + (rnd() - 0.5) * live * 0.012;
    out.push({ date, open: +(base * 0.997).toFixed(2), high: +(base * 1.008).toFixed(2), low: +(base * 0.99).toFixed(2), close: +base.toFixed(2), volume: 1000000 });
  });
  if (symbol === 'AAPL') {
    out.splice(-3, 3,
      { date: '2026-10-12', open: 98.8, high: 99.9, low: 98.1, close: 99.3, volume: 1 },
      { date: '2026-10-13', open: 99.4, high: 101.2, low: 99, close: 100.9, volume: 1 },
      { date: '2026-10-14', open: 101, high: 104.1, low: 100.6, close: live, volume: 1 });
  }
  return out.reverse(); // the API answers newest-first
}

function installFetch(spec, onAsk) {
  const real = globalThis.__sheetSmokeRealFetch || globalThis.fetch.bind(globalThis);
  globalThis.__sheetSmokeRealFetch = real;
  globalThis.fetch = async (input, init) => {
    const url = new URL(typeof input === 'string' ? input : input.url, window.location.origin);
    const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });
    if (url.pathname === '/api/stocks/historical') {
      const symbol = url.searchParams.get('symbol');
      const tf = url.searchParams.get('timeframe');
      const delay = Number(QP.get('delay') || 0);
      if (delay) await new Promise((r) => setTimeout(r, delay));
      if (QP.get('fail') === '1') return json({ success: false, error: 'SMOKE ONLY: ?fail=1' }, 500);
      const live = symbol === spec.symbol ? spec.live : (LIVE_OF[symbol] ?? 100);
      if (tf === '1w') {
        const wk = new Map();
        for (const b of dailyBars(symbol, live).slice().reverse()) {
          const t = new Date(`${b.date}T00:00:00Z`); t.setUTCDate(t.getUTCDate() - ((t.getUTCDay() + 6) % 7));
          const k = t.toISOString().slice(0, 10); const w = wk.get(k);
          if (!w) wk.set(k, { ...b, date: k }); else { w.high = Math.max(w.high, b.high); w.low = Math.min(w.low, b.low); w.close = b.close; w.volume += b.volume; }
        }
        return json({ success: true, data: [...wk.values()].reverse(), timeframe: tf });
      }
      if (tf === '30m' || tf === '1m' || tf === '5m') {
        // Intraday bars from the fixture's own price: a gentle walk from 2.5 % under it, ending at it now.
        const out = [];
        const step = tf === '30m' ? 1800000 : tf === '5m' ? 300000 : 60000;
        const perDay = tf === '30m' ? 13 : tf === '5m' ? 78 : 390;
        const days = tf === '1m' ? ['2026-10-14'] : ['2026-10-12', '2026-10-13', '2026-10-14'];
        const times = [];
        for (const day of days) for (let k = 0; k < perDay; k += 1) { const t = Date.parse(`${day}T13:30:00.000Z`) + k * step; if (t <= Date.now()) times.push(t); }
        times.forEach((t, i) => {
          const f = times.length > 1 ? i / (times.length - 1) : 1;
          const base = live * (0.975 + 0.025 * f) + live * 0.002 * Math.sin(i / 3);
          const close = i === times.length - 1 ? live : base;
          const open = close * (1 + 0.0012 * Math.sin(i * 1.7)); // some bars close below their open (red), some above (green)
          out.push({ date: new Date(t).toISOString(), open: +open.toFixed(2), high: +(Math.max(open, close) * 1.001).toFixed(2), low: +(Math.min(open, close) * 0.999).toFixed(2), close: +close.toFixed(2), volume: 1000 });
        });
        return json({ success: true, data: out.reverse(), timeframe: tf });
      }
      return json({ success: true, data: tf === '1d' ? dailyBars(symbol, live) : [], timeframe: tf });
    }
    if (url.pathname === '/api/stocks/prices') {
      const sym = (url.searchParams.get('symbols') || '').split(',').filter(Boolean);
      const prices = Object.fromEntries(sym.map((s) => {
        const live = s === spec.symbol ? spec.live : (LIVE_OF[s] ?? 100);
        const bars = dailyBars(s, live);
        const today = bars[0]; const prev = bars[1];
        return [s, {
          price: live, previousClose: prev.close, open: today.open, high: Math.max(today.high, live), low: Math.min(today.low, live),
          change: +(live - prev.close).toFixed(2), changePercent: +(((live - prev.close) / prev.close) * 100).toFixed(2), timestamp: Math.floor(Date.now() / 1000),
        }];
      }));
      return json({ success: true, count: Object.keys(prices).length, prices });
    }
    if (url.pathname === '/api/stocks/fundamentals') {
      const symbol = url.searchParams.get('symbol');
      return PROFILES[symbol] ? json({ success: true, data: PROFILES[symbol] }) : json({ success: false }, 404);
    }
    // Nov 13: every price comes from the fixtures — the rankings routes are refused too (the tabs show their empty state).
    if (url.pathname === '/api/why-moving') {
      const body = JSON.parse(init?.body || '{}');
      await new Promise((r) => setTimeout(r, 900));
      return json({ success: true, data: WHY(body.symbol, body.name) });
    }
    if (url.pathname === '/api/agent/chat') {
      const body = JSON.parse(init?.body || '{}');
      await new Promise((r) => setTimeout(r, 1200));
      return json(onAsk(body));
    }
    if (url.pathname.startsWith('/api/')) return json({ success: false }, 404);
    return real(input, init);
  };
}

function clearFixtureCache() {
  try {
    for (let i = localStorage.length - 1; i >= 0; i -= 1) {
      const k = localStorage.key(i);
      if (k && /ohlcv_/.test(k)) localStorage.removeItem(k); // every symbol: no real cached bar reaches the chart
    }
  } catch { /* storage unavailable */ }
}

function BrowseSmoke({ spec, state }) {
  useMemo(() => { installFetch(spec, () => ({ error: 'SMOKE ONLY: no Ask in browse' })); clearFixtureCache(); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { document.title = `SMOKE · ${state}`; }, [state]);
  return (
    <div style={{ minHeight: '100vh', background: 'var(--ft-bg-dashboard)' }}>
      <div style={{ position: 'fixed', top: 2, right: 8, zIndex: 100000, fontSize: 9, color: 'var(--ft-ink-3)', fontFamily: 'monospace', pointerEvents: 'none' }}>SMOKE · {state}</div>
      <AssetResearchModal
        asset={{ symbol: spec.symbol, name: spec.name, price: spec.live, percentChange: spec.change }}
        onClose={() => {}}
        actionConfig={{ label: 'Add to Watchlist', onClick: () => { window.alert('SMOKE ONLY — Add to Watchlist adds the name in the app.'); }, variant: 'primary' }}
        version={2}
      />
    </div>
  );
}

function BattleSmoke({ spec, state }) {
  const [battle, setBattle] = useState(() => {
    const b = JSON.parse(JSON.stringify({ ...BATTLES[spec.battle], ...(spec.over || {}) }));
    if (QP.get('name')) b.agentContext.agentName = QP.get('name');
    if (QP.get('arch')) b.agentContext.archetype = QP.get('arch');
    if (QP.get('long') === '1') {
      const e2 = b.evaluations.find((e) => e.evalId === 'e2');
      if (e2) e2.rationale = `Holding the book through the midday chop. ${spec.symbol} is still printing higher lows above VWAP on rising volume after reclaiming the opening range, the sector tape is firm, rates are calm and the position has room to the next rung, so the trend is intact and the position stays on the board for now. ETH has gone quiet.`;
      if (b.agentContext?.equippedHypothesis) b.agentContext.equippedHypothesis.statement = 'Big caps with clean balance sheets and pricing power keep leading while rates hold steady through the quarter; buy the leaders on quiet pullbacks into the 20-day average and cut them fast when they lose the prior week low on volume.';
      if (b.directive) b.directive = { ...b.directive, text: `Keep ${spec.symbol} unless it closes under the opening range twice; if it does, rotate into the strongest name on the bench and tell me why in one line before the close, and do not add to anything that is already up more than five percent today.` };
    }
    return b;
  });
  // The canned Ask reads the battle as it is NOW (never the first render's copy).
  const battleRef = useRef(battle);
  battleRef.current = battle;
  useMemo(() => {
    installFetch(spec, (body) => {
      const n = (battleRef.current.chatBudgetUsed || 0) + 1;
      const exchangeId = `smoke-${Math.random().toString(16).slice(2, 10)}-0000-4000-8000-000000000000`;
      const items = body?.researchAsk?.items || [];
      const reply = `SMOKE ONLY — a canned reply, no model was called. ${items.length ? `I lean on item 1: ${items[0].fact}` : 'There was nothing in the pack.'}`;
      setTimeout(() => setBattle((b) => ({ ...b, chatBudgetUsed: n, chatExchanges: [...(b.chatExchanges || []), { exchangeId, userMessage: body.message, agentResponse: reply, source: 'research_modal', timestamp: new Date().toISOString() }] })), 1500);
      return { agentMessage: reply, exchangeId, exchangeNumber: n, budgetTotal: 10, hasDirective: false, directive: null, mode: 'battle' };
    });
    clearFixtureCache();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { document.title = `SMOKE · ${state}`; }, [state]);

  const sym = spec.symbol;
  const at = ['star', 'core', 'support'].flatMap((tier) => (battle.portfolio?.[tier] || []).map((p, slot) => ({ p, tier, slot }))).find((x) => x.p?.symbol === sym) ?? null;
  const pos = at?.p ?? null;
  const row = pos?.stockThresholdReceipt && battle.scoring?.stockThresholdModel ? enrichHeldPosition(pos, at.tier, { stockBattle: battle, stockSide: 'agent', stockSlot: at.slot }) : { symbol: sym, name: spec.name, ...(pos || {}) };
  const asset = buildResearchAsset(row, { livePrices: { [sym]: spec.live }, thresholds: { [sym]: { threshold: 2.5 } }, startingPrices: battle.portfolio?.startingPrices || {}, useDefaultThreshold: true });
  const sheetContext = {
    battleId: battle.id,
    agentId: battle.agentId,
    archetype: battle.agentContext?.archetype ?? null,
    agentName: battle.agentContext?.agentName ?? null,
    row: { held: false, positionId: pos?.positionId ?? null },
    ...(spec.incumbent ? { incumbent: spec.incumbent } : {}),
    onOpenCockpit: () => { window.alert('SMOKE ONLY — → Cockpit opens the battle’s cockpit in the app.'); },
    battle,
    calls: spec.calls === 'six' ? CALLS_SIX : CALLS,
    rankings: spec.rankings === 'book' ? BOOK_RANKINGS : RANKINGS,
    // As the screen hands it: the header's own digits and lead.
    standing: (() => {
      const player = battle.scoreState?.currentScore ?? 0;
      const opponent = battle.scoreState?.opponentScore ?? 0;
      return { player, opponent, digits: 0, you: formatScoreDisplay(player), them: formatScoreDisplay(opponent), lead: player > opponent ? 'player' : player < opponent ? 'cpu' : 'tie' };
    })(),
    directive: battle.directive ?? null,
  };
  return (
    <div style={{ minHeight: '100vh', background: 'var(--ft-bg-dashboard)' }}>
      <div style={{ position: 'fixed', top: 2, right: 8, zIndex: 100000, fontSize: 9, color: 'var(--ft-ink-3)', fontFamily: 'monospace', pointerEvents: 'none' }}>SMOKE · {state}</div>
      <AssetResearchModal asset={asset} onClose={() => {}} showActionButton={false} isGameContext version={2} defaultTab="baggerbomb" defaultTimeframe="bomb" wsPrice={spec.live} sheetContext={sheetContext}
        {...(QP.get('bomb') !== '0' ? { bombContext: agentBombContext(battle, sym, Date.now(), { battleId: battle.id, positionId: pos?.positionId ?? null }) } : {})} />
    </div>
  );
}

export default function ShellSmokeScreen({ state }) {
  const spec = STATES[state] || STATES.held_tf;
  installClock(NOW);
  return spec.browse ? <BrowseSmoke spec={spec} state={state} /> : <BattleSmoke spec={spec} state={state} />;
}
